const readingTimePerSession = tvTimePerSession / 2;
const totalTimePerSession = tvTimePerSession + readingTimePerSession;
const sessionsPerWeek = 3;
const weeks = 4;

// Total time per week
const totalTimePerWeek = totalTimePerSession * sessionsPerWeek;

// Total time over 4 weeks
const totalTimeIn4Weeks = totalTimePerWeek * weeks;

// Output the result
totalTimeIn4Weeks;
```
